insert into projects (name, type, kind, device, status, icon, type_label, summary_es, summary_en, long_es, long_en, highlights_es, highlights_en, stack, published, sort_order) values
('Velamentum', '3d', 'front', 'browser', 'wip', 'box', '3D / E-COMMERCE',
 'Marca de ropa con configurador 3D. Blender a GLB, frontend Angular standalone.',
 'Clothing brand with a 3D configurator. Blender to GLB, standalone Angular frontend.',
 'Proyecto personal de marca: configurador 3D donde el usuario rota y personaliza prendas en tiempo real. Modelado en Blender, exportado a GLB y renderizado en Three.js sobre un frontend Angular standalone con servicios reactivos y rutas lazy. Backend en Spring Boot con esquema MySQL.',
 'Personal brand project: a 3D configurator where users rotate and customize garments in real time. Modeled in Blender, exported to GLB and rendered in Three.js over a standalone Angular frontend with reactive services and lazy routes. Spring Boot backend with a MySQL schema.',
 ARRAY['Configurador 3D interactivo con GLB optimizado', 'Componentes standalone + servicios reactivos', 'Identidad editorial blanco / negro / rojo'],
 ARRAY['Interactive 3D configurator with optimized GLB', 'Standalone components + reactive services', 'Editorial white / black / red identity'],
 ARRAY['Angular', 'Three.js', 'Blender', 'Spring Boot'],
 true, 0),
('controlPanel', 'web', 'front', 'browser', 'live', 'activity', 'DASHBOARD',
 'Panel de control con gráficos interactivos y datos de analítica en tiempo real.',
 'Control panel with interactive charts and real-time analytics data.',
 'Aplicación de panel de control que visualiza datos de analítica mediante gráficos interactivos. Enfoque en jerarquía de información, lectura rápida de métricas y componentes reutilizables.',
 'Control panel application that visualizes analytics data through interactive charts. Focused on information hierarchy, fast metric reading and reusable components.',
 ARRAY['Gráficos interactivos y filtrables', 'Layout de dashboard responsive', 'Componentes de datos reutilizables'],
 ARRAY['Interactive, filterable charts', 'Responsive dashboard layout', 'Reusable data components'],
 ARRAY['TypeScript', 'Charts', 'Angular'],
 true, 1),
('Cauce', 'tool', 'front', 'phone', 'wip', 'cpu', 'FINANCE APP',
 'App de finanzas personales para LATAM. Offline-first, resumen mensual 3D.',
 'Personal finance app for LATAM. Offline-first, 3D monthly summary.',
 'App móvil de finanzas personales para el mercado colombiano y LATAM. Arquitectura offline-first con SQLite local y un resumen mensual animado en 3D —''Tu historia financiera''— con TresJS. Identidad propia en terracota, violeta y near-black.',
 'Mobile personal finance app for the Colombian and LATAM market. Offline-first architecture with local SQLite and a 3D animated monthly summary —''Your financial story''— with TresJS. Own identity in terracotta, violet and near-black.',
 ARRAY['Offline-first con SQLite + Capacitor', 'Resumen mensual 3D con TresJS', 'Diseño propio: Instrument Serif + DM Sans'],
 ARRAY['Offline-first with SQLite + Capacitor', '3D monthly summary with TresJS', 'Own design: Instrument Serif + DM Sans'],
 ARRAY['Vue 3', 'Ionic', 'Capacitor', 'SQLite'],
 true, 2),
('Crud_usuarios', 'web', 'back', NULL, 'live', 'layers', 'FULL CRUD / API',
 'CRUD de usuarios con arquitectura modular y servicios reactivos.',
 'User CRUD with modular architecture and reactive services.',
 'Gestión completa de usuarios: alta, lectura, edición y borrado sobre una API REST. Arquitectura modular en TypeScript con separación clara de capas y validación de datos.',
 'Full user management: create, read, update and delete over a REST API. Modular TypeScript architecture with clear layer separation and data validation.',
 ARRAY['API REST con operaciones CRUD completas', 'Validación y manejo de errores', 'Arquitectura modular por capas'],
 ARRAY['REST API with full CRUD operations', 'Validation and error handling', 'Modular layered architecture'],
 ARRAY['TypeScript', 'Node.js', 'REST'],
 true, 3),
('chatBot', 'tool', 'back', NULL, 'archive', 'terminal', 'API / PYTHON',
 'API de chatbot en Python para automatización de respuestas.',
 'Chatbot API in Python for response automation.',
 'Servicio de chatbot construido en Python: recibe mensajes, los procesa y devuelve respuestas automatizadas a través de una API. Base para integraciones de soporte y automatización.',
 'Chatbot service built in Python: receives messages, processes them and returns automated responses through an API. A base for support and automation integrations.',
 ARRAY['Procesamiento de mensajes vía API', 'Respuestas automatizadas', 'Base para integraciones'],
 ARRAY['Message processing via API', 'Automated responses', 'Base for integrations'],
 ARRAY['Python', 'FastAPI'],
